//! Retry configuration.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RetryConfig {
    /// Total attempts allowed, including the first call. Must be >= 1.
    pub max_attempts: u32,
    /// Base delay before the first retry, in milliseconds.
    pub base_delay_ms: u64,
    /// Maximum delay between retries, in milliseconds.
    pub max_delay_ms: u64,
}

impl RetryConfig {
    /// Returns the delay for the retry after `retry_number` failed attempts.
    pub(crate) fn delay_for_retry(&self, retry_number: u32) -> u64 {
        let exponent = retry_number.saturating_sub(1);
        let delay = self.base_delay_ms.saturating_mul(2u64.saturating_pow(exponent));
        delay.min(self.max_delay_ms)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn delay_doubles_and_saturates_at_maximum() {
        let config = RetryConfig {
            max_attempts: 10,
            base_delay_ms: 100,
            max_delay_ms: 250,
        };

        assert_eq!(config.delay_for_retry(1), 100);
        assert_eq!(config.delay_for_retry(2), 200);
        assert_eq!(config.delay_for_retry(3), 250);
        assert_eq!(config.delay_for_retry(4), 250);
    }
}

